from fastapi import FastAPI, Depends, HTTPException, status

app = FastAPI()

def get_usuario_actual(token: str = "token_simulado"):
    if token != "token_valido_123":
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Token inválido o expirado"
        )
    return {"id": 1, "username": "koda_specialist"}

@app.get("/perfil")
def ver_perfil(usuario = Depends(get_usuario_actual)):
    return {"mensaje": "Acceso autorizado", "usuario": usuario}
